# calculator_spec.gr
# Run with: gr spec calculator_spec.gr

describe "Calculator" {
    it "adds two numbers" {
        expect(2 + 2).to_equal(4)
    }

    it "subtracts numbers" {
        expect(10 - 3).to_equal(7)
    }

    it "multiplies numbers" {
        expect(6 * 7).to_equal(42)
    }
}

describe "List" {
    context "when empty" {
        it "has length 0" {
            assert(expect([]).to_have_length(0))
        }

        it "is empty" {
            assert(expect([]).to_be_empty())
        }
    }

    context "when populated" {
        it "has correct length" {
            assert(expect([1, 2, 3]).to_have_length(3))
        }

        it "contains elements" {
            assert(expect([1, 2, 3]).to_contain(2))
        }
    }
}

describe "Equality and Truthiness Matchers" {
    it "checks equality with to_equal" {
        expect(42).to_equal(42)
    }

    it "checks truthiness" {
        assert(expect(true).to_be_truthy())
        assert(expect(1).to_be_truthy())
    }

    it "checks falsiness" {
        assert(expect(false).to_be_falsy())
        assert(expect(none).to_be_falsy())
    }

    it "checks for none" {
        assert(expect(none).to_be_none())
    }

    it "checks type" {
        assert(expect(42).to_be_a("num"))
        assert(expect("hello").to_be_a("string"))
        assert(expect([1, 2]).to_be_a("list"))
        assert(expect({"a": 1}).to_be_a("map"))
    }
}

describe "Comparison Matchers" {
    it "checks greater than" {
        assert(expect(10).to_be_greater_than(5))
    }

    it "checks less than" {
        assert(expect(3).to_be_less_than(8))
    }

    it "checks at least (>=)" {
        assert(expect(5).to_be_at_least(5))
        assert(expect(6).to_be_at_least(5))
    }

    it "checks at most (<=)" {
        assert(expect(5).to_be_at_most(5))
        assert(expect(4).to_be_at_most(5))
    }
}

describe "Approximate Matching" {
    it "checks floating point closeness" {
        pi = 3.14159
        assert(expect(pi).to_be_close_to(3.14, 0.01))
    }

    it "handles tiny differences" {
        result = 0.1 + 0.2
        assert(expect(result).to_be_close_to(0.3, 0.001))
    }
}

describe "Exception Testing" {
    it "catches a raised ValueError" {
        assert(expect(fn() {
            raise ValueError("bad input")
        }).to_raise("ValueError"))
    }

    it "catches division by zero" {
        assert(expect(fn() {
            x = 10 / 0
        }).to_raise("RuntimeError"))
    }
}

# Use .negate() instead of .not() — gspec has no .not() method

describe "Negated Matchers" {
    it "checks inequality" {
        assert(expect(5).negate().to_equal(10))
    }

    it "checks not empty" {
        assert(expect([1, 2, 3]).negate().to_be_empty())
    }

    it "checks does not contain" {
        assert(expect([1, 2, 3]).negate().to_contain(99))
    }
}

describe "Stack" {
    before_each {
        items = []
    }

    it "starts empty" {
        assert(expect(items).to_be_empty())
    }

    it "allows pushing elements" {
        items.append(42)
        assert(expect(items).to_have_length(1))
        assert(expect(items).to_contain(42))
    }

    it "each test gets a fresh list" {
        assert(expect(items).to_be_empty())
    }
}

describe "Feature Under Development" {
    it "works for basic case" {
        expect(1 + 1).to_equal(2)
    }

    # Use xit to skip a test — it will be reported but not run
    xit "handles edge case" {
        expect(none).to_equal(0)
    }

    # Use pending to mark not-yet-implemented tests
    pending("needs async support")
}

describe "Multiple Assertions" {
    it "validates a map fully" {
        config = {"host": "localhost", "port": 8080}
        assert(expect(config).to_be_a("map"))
        assert(expect(config["host"]).to_equal("localhost"))
        assert(expect(config["port"]).to_equal(8080))
    }

    it "validates a list fully" {
        nums = [10, 20, 30]
        assert(expect(nums).to_have_length(3))
        assert(expect(nums).to_contain(20))
        assert(expect(nums).negate().to_be_empty())
    }
}

describe "Graph" {
    it "adds and retrieves nodes" {
        g = graph { type: :directed }
        g.add_node("A", 1)
        g.add_node("B", 2)
        assert(expect(g.node_count()).to_equal(2))
        assert(expect(g.has_node("A")).to_be_truthy())
    }

    it "connects nodes with edges" {
        g = graph { type: :directed }
        g.add_node("A", 1)
        g.add_node("B", 2)
        g.add_edge("A", "B", "link")
        assert(expect(g.edge_count()).to_equal(1))
        assert(expect(g.has_path("A", "B")).to_be_truthy())
    }
}

describe "List Operations" {
    it "appends elements" {
        items = [1, 2]
        items.append(3)
        assert(expect(items).to_have_length(3))
        assert(expect(items).to_contain(3))
    }

    it "maps over elements" {
        nums = [1, 2, 3]
        doubled = nums.map(x => x * 2)
        assert(expect(doubled).to_equal([2, 4, 6]))
    }

    it "filters elements" {
        nums = [1, 2, 3, 4, 5]
        evens = nums.filter(x => x % 2 == 0)
        assert(expect(evens).to_equal([2, 4]))
    }
}

describe "Error Conditions" {
    it "raises custom errors" {
        assert(expect(fn() {
            raise ValueError("invalid input")
        }).to_raise("ValueError"))
    }

    it "catches specific error types" {
        msg = ""
        try {
            raise TypeError("wrong type")
        } catch TypeError as e {
            msg = e.to_string()
        }
        assert(expect(msg).to_equal("wrong type"))
    }
}

describe "Collection Matchers" {
    it "checks if list contains an element" {
        assert(expect([10, 20, 30]).to_contain(20))
    }

    it "checks if list is empty" {
        assert(expect([]).to_be_empty())
    }

    it "checks list length" {
        assert(expect([1, 2, 3, 4]).to_have_length(4))
    }

    it "checks string contains substring" {
        assert(expect("hello world").to_contain("world"))
    }

    it "checks negated collection matchers" {
        assert(expect([1, 2, 3]).negate().to_be_empty())
        assert(expect([1, 2, 3]).negate().to_contain(99))
    }
}
